sysauto_script.script:
// This script goes through active Telework Agreements and verifies that the Employee's "Manager" 
// and "Service Area" listed in their Telework Agreement match with what's in their (Employee's) User record.
// If they do not match, the Telework Agreement is updated.
// 
// Note: it is assumed that Employee's User record in ServiceNow, which is synched nightly
// (from AD/PeopleCentral/Unit4), will contain correct Manager and Service Area information.
// 
// Number of records to process is set in call updateTeleworkAgreementManagerServiceArea() on LAST line
// of code below. Set to -1 for all records.

function updateTeleworkAgreementManagerServiceArea(numRecords, doUpdate) {

    var grTele = new GlideRecord('x_hccc_hoc_ohs_telework_agreement');

    grTele.addEncodedQuery("active=true");
    //grTele.setWorkflow(false);		// Setting these to false stops auditing from working
    //grTele.autoSysFields(false);
    if (numRecords != -1) grTele.setLimit(numRecords);
    grTele.query();

    gs.info("Telework: Number records found: " + grTele.getRowCount());

    var numCount = 0;

    while (grTele.next()) {

        var managerUpdated = 0;
        var serviceareaUpdated = 0;

        // Get User record for the Employee of current Teleweork Agreement
        var userId = grTele.subject_person;
        var grUser = new GlideRecord('sys_user');

        grUser.get(userId);

        var infoStr = "Telework: # " + grTele.number.toString() + " - Employee: " + grUser.name.toString();

        // Check if Manager has changed	
        if (grTele.manager_name != grUser.manager) {
            if (doUpdate != 0) {
                infoStr += " - MANAGER updated";
                grTele.setValue('manager_name', grUser.manager);
            } else infoStr += " - MANAGER to update";
            managerUpdated = 1;
        }

        // Check if Service Area (i.e. Business Unit) has changed
        if (grTele.employee_service_area != grUser.department.business_unit) {
            if (doUpdate != 0) {
                infoStr += " - SERVICE AREA updated";
                grTele.setValue('employee_service_area', grUser.department.business_unit);
            } else infoStr += " - SERVICE AREA to update";
            serviceareaUpdated = 1;
        }

        if ((managerUpdated != 0) || (serviceareaUpdated != 0)) {
            if (doUpdate != 0) grTele.update();
            gs.info(infoStr);
            numCount++;
        }

        //infoStr += "\n";

    }

    if (doUpdate != 0) gs.info("Telework: Number records updated: " + numCount.toString());
    else gs.info("Telework: Number records that require updating: " + numCount.toString());

}

// 1st parameter = # of records to process **OR** -1 for all records that fit the criteria
// 2nd parameter = 0 to NOT update and only generate list of records to be updated **OR** 1 to UPDATE and generate list
// Example: updateTeleworkAgreementManagerServiceArea(100, 0) will process 100 records but NOT update them
// Example: updateTeleworkAgreementManagerServiceArea(-1, 1) will process ALL records and update them
updateTeleworkAgreementManagerServiceArea(-1, 1);
